const $=s=>document.querySelector(s),app=$('#app'),modal=$('#modal');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={flashcards:'M6 5h15v12H6V5ZM3 8v12h15M9 9h8M9 13h5',coffee:'M5 9h12v5a6 6 0 0 1-12 0V9Zm12 1h2a3 3 0 0 1 0 6h-2M3 22h17M8 5c-3-2 3-2 0-5M13 5c-3-2 3-2 0-5',home:'m3 10 9-7 9 7M5 9v12h5v-7h4v7h5V9',tasks:'M7 3h10a3 3 0 0 1 3 3v14H4V6a3 3 0 0 1 3-3Zm0 9 3 3 7-7',timer:'M9 2h6M12 6a8 8 0 1 0 0 16 8 8 0 0 0 0-16Zm0 4v5l3 2M18 5l2-2',book:'M12 5v16M3 4c4-1 6 0 9 2 3-2 5-3 9-2v15c-4-1-6 0-9 2-3-2-5-3-9-2V4Z',plant:'M12 22V11M12 14C3 15 3 5 3 5s9 0 9 9Zm0-4c0-8 9-8 9-8s0 9-9 8',gift:'M3 9h18v5H3V9Zm2 5v8h14v-8M12 9v13M12 9C2 9 6-1 12 9Zm0 0c10 0 6-10 0 0',chart:'M4 21V12h3v9M11 21V7h3v14M18 21V3h3v18',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8Zm-2-5h4l1 3 3 1 3-1 2 4-2 2v3l2 2-2 4-3-1-3 1-1 3h-4l-1-3-3-1-3 1-2-4 2-2v-3l-2-2 2-4 3 1 3-1 1-3',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14Zm5 12 6 6',bell:'M5 17h14l-2-3V9a5 5 0 0 0-10 0v5l-2 3Zm5 4h4',play:'m8 5 12 7-12 7V5',pause:'M8 5v14M16 5v14',reset:'M4 9a8 8 0 1 1 0 8M4 3v6h6',music:'M9 18V5l11-2v13M9 5v4l11-2M6 15a3 3 0 1 0 0 6 3 3 0 0 0 0-6',expand:'M3 8V3h5M16 3h5v5M21 16v5h-5M8 21H3v-5',plus:'M12 4v16M4 12h16',logout:'M9 3H3v18h6M9 12h12m-5-5 5 5-5 5'};
const icon=n=>`<span class="icon"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.coffee}"/></svg></span>`;
const today=()=>new Date().toLocaleDateString('en-CA'),uid=()=>crypto.randomUUID();
const initial=()=>({name:'Study buddy',avatar:'🐱',avatarId:'maple',avatarPosition:{id:'avatar',gx:5,gy:4,rotation:0},xp:0,coins:0,classes:['General'],tasks:[],cards:[],decks:[],notebooks:[],notebookFolders:[],alarms:[],sessions:[],owned:['table','chair','counter'],placed:[{id:uid(),item:'table',gx:3,gy:4,rotation:0},{id:uid(),item:'chair',gx:2,gy:4,rotation:0},{id:uid(),item:'counter',gx:5,gy:1,rotation:0}],quests:{},scratch:'',settings:{focus:25,short:5,long:15,daily:60,weekly:300,dark:false,timeZone:window.CoffeeClock.defaultTimeZone(),ambientSound:"rain",soundVolume:.35,endSound:"bell"},exam:{name:'Your next exam',date:'',goal:10},theme:'spring',unlockedThemes:['daytime','spring'],plantCare:{stage:0,lastDate:today(),goal:60,completed:false,reward:0}});
const demo=()=>({...initial(),coins:10000,testResetVersion:1});
let state,user=null,guest=false,cloud=null,saveQueue=Promise.resolve(),view='dashboard',filter='all',classFilter='all',shopFilter='All',reviewIndex=0,flipped=false,quiz=false,selected=null,moving=null,syncError=false,ready=false,authMode='login',activeDeck=null,deckClassFilter='all',deckImport=null,pendingRestore=null,pendingDeckDraft=null;
let flashcardFullscreen=false,nativeFlashcardFullscreen=false;
let timer={mode:'focus',seconds:1500,running:false,deadline:0,total:1500,subject:'General',sessionId:null},audio=null;
const navs=[['dashboard','home','Dashboard'],['tasks','tasks','Tasks'],['focus','timer','Focus mode'],['study','flashcards','Study tools'],['notebooks','book','Notebooks'],['cafe','coffee','My café'],['rewards','gift','Rewards'],['stats','chart','Statistics'],['settings','settings','Settings']];
function pageStorageKey(){return 'cram-coffee-last-page-'+(guest?'guest':user?.uid||'signed-out');}
function rememberPage(){if(!ready||!guest&&!user)return;try{localStorage.setItem(pageStorageKey(),view);localStorage.setItem('cram-coffee-session',guest?'guest':'account');}catch{}}
function restorePage(){let saved;try{saved=localStorage.getItem(pageStorageKey());}catch{}view=navs.some(([id])=>id===saved)?saved:'dashboard';}
function resumeGuestSession(){try{return localStorage.getItem('cram-coffee-session')==='guest';}catch{return false;}}
function clearRememberedSession(){try{localStorage.removeItem('cram-coffee-session');}catch{}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').classList.remove('visible'),4000);}
function save(){clearTimeout(notebookSaveTimer);notebookSaveTimer=null;notebookDirty=false;syncPlantCare();const snapshot=structuredClone(state);if(guest){try{localStorage.setItem('cram-coffee-guest',JSON.stringify(snapshot));}catch{toast('Browser storage is full. Export your progress in Settings.');}}else if(user&&cloud){const account=user;saveQueue=saveQueue.catch(()=>{}).then(()=>cloud.setDoc(cloud.doc(cloud.db,'users',account.uid),{data:snapshot})).then(()=>{syncError=false;}).catch(e=>{syncError=true;toast('Cloud save failed. Keep this tab open and retry in Settings.');console.error(e);});}document.body.classList.toggle('dark',!!state.settings.dark);}
function loadGuest(silent=false){audio?.stop();user=null;guest=true;try{state=JSON.parse(localStorage.getItem('cram-coffee-guest'))||demo();}catch{state=demo();}if(state.testResetVersion!==1){try{localStorage.setItem('cram-coffee-guest-before-reset',JSON.stringify(state));}catch{}state=demo();}if(!state.owned.includes('counter')){state.owned.push('counter');state.placed.push({id:uid(),item:'counter',gx:2,gy:1,rotation:0});}state.avatarId||='maple';state.avatarPosition||={id:'avatar',gx:5,gy:4,rotation:0};migrateCafe();ensureDecks();cafeGuests=[];lastGuestArrival=0;ready=true;timer.mode='focus';resetTimer();restorePage();save();render();if(!silent)toast('Guest café opened. Progress is saved in this browser.');}
function headerDateTime(){const now=new Date(),value=window.CoffeeClock.format(now,state.settings.timeZone);return '<span class="header-datetime"><span class="date" data-header-date>'+esc(value.date)+'</span><time class="header-clock" data-header-clock datetime="'+now.toISOString()+'" title="'+esc(value.zone)+'">'+esc(value.time)+'</time></span>';}
function updateHeaderClock(){if(!ready||!state)return;const now=new Date(),value=window.CoffeeClock.format(now,state.settings.timeZone);document.querySelectorAll('[data-header-date]').forEach(el=>el.textContent=value.date);document.querySelectorAll('[data-header-clock]').forEach(el=>{el.textContent=value.time;el.dateTime=now.toISOString();el.title=value.zone;});}
setInterval(updateHeaderClock,1000);
function greeting(){const h=new Date().getHours();return h<12?'Good morning!':h<18?'Good afternoon!':'Good evening!';}
function syncPlantCare(){const result=window.CoffeePlant.update(state,today());if(result.xp)rememberThemeUnlocks();return result.changed;}
function plantMarkup(){const c=state.plantCare,name=window.CoffeePlant.names[c.stage],studied=dailySessions().reduce((total,s)=>total+s.minutes,0);return '<section class="card plant-card"><div class="plant-top"><h2>Your coffee plant</h2></div><img class="plant-img" src="'+window.CoffeePlant.image(c.stage)+'" alt="'+name+' coffee plant in a terracotta pot beside a smiling cup"><div class="plant-body"><h3>Coffee plant <span style="float:right">🌿</span></h3><small>Care level '+c.stage+' / 4 · '+name+'</small><div class="progress" style="margin-top:12px"><span style="width:'+c.stage*25+'%"></span></div><p class="plant-daily">Today: '+Math.round(studied)+' / '+c.goal+' study minutes</p><small>'+(c.completed?'✓ Daily goal met · +'+c.reward+' XP':c.stage===4?'Meet today’s goal to keep it thriving · +15 XP':'Meet today’s goal to grow one stage · +5 XP')+'</small><p class="plant-care-help">A missed day takes it back one stage. Your care level is separate from your café level.</p></div></section>';}
function level(){return Math.floor(state.xp/1000)+1;}
const themeLevels={daytime:1,spring:1,evening:2,autumn:3,coastal:4,winter:5,greenhouse:6,celestial:7};
const furnitureLevels={armchair:2,shelf:2,desk:3,'wide-shelf':3,sofa:4,cart:4,employee:4,pastry:5};
function itemLevel(id){return furnitureLevels[id]||1;}
function itemUnlocked(id){return level()>=itemLevel(id);}
function themeUnlocked(id){return level()>=(themeLevels[id]||1)||(state.unlockedThemes||[]).includes(id);}
function rememberThemeUnlocks(){state.unlockedThemes=[...new Set([...(state.unlockedThemes||[window.CafeCharacters.theme(state.theme).id]),...Object.keys(themeLevels).filter(id=>level()>=themeLevels[id])])];}
function unlockRequirement(required){return 'Level '+required+' · '+((required-1)*1000).toLocaleString()+' XP';}
function themePicker(){showModal('Choose your café theme','<p class="muted">Earn XP to unlock new café themes. Unlocked themes are free to use.</p><div class="theme-picker">'+window.CafeCharacters.themes.map(t=>'<button class="theme-option '+(window.CafeCharacters.theme(state.theme).id===t.id?'chosen':'')+' '+(themeUnlocked(t.id)?'':'locked-theme')+'" data-theme="'+t.id+'" '+(themeUnlocked(t.id)?'':'disabled')+'>'+window.CafeCharacters.roomPreview(t.id)+'<b>'+t.name+'</b><small>'+(themeUnlocked(t.id)?'Unlocked':unlockRequirement(themeLevels[t.id]))+'</small></button>').join('')+'</div>');}
function levelUnlocksMarkup(){return '<section class="card level-unlocks"><h2>Grow your café with XP</h2><p class="muted">Every 1,000 XP earns a level. Themes unlock for free; furniture and the barista unlock for purchase with café coins.</p>'+Array.from({length:6},(_,i)=>{const required=i+2,names=[...window.CafeCharacters.themes.filter(t=>themeLevels[t.id]===required).map(t=>t.name+' theme'),...products.filter(p=>itemLevel(p.id)===required).map(p=>p.name)];return '<div class="unlock-row"><b>'+unlockRequirement(required)+'</b><span>'+names.map(esc).join(' · ')+'</span><small>'+(level()>=required?'Unlocked':((required-1)*1000-state.xp).toLocaleString()+' XP to go')+'</small></div>';}).join('')+'</section>';}
function streak(){const dates=new Set(state.sessions.map(s=>s.date));let d=new Date(),n=0;if(!dates.has(today()))d.setDate(d.getDate()-1);while(dates.has(d.toLocaleDateString('en-CA'))){n++;d.setDate(d.getDate()-1);}return n;}
function minutes(){return state.sessions.reduce((a,s)=>a+s.minutes,0);}
function dailySessions(){return state.sessions.filter(s=>s.date===today());}
function reward(xp,coins){state.xp+=xp;state.coins+=coins;rememberThemeUnlocks();save();}
function taskRows(tasks,full=false){return tasks.length?tasks.map(t=>`<div class="task-row ${t.done?'done':''}"><input class="check" type="checkbox" aria-label="Complete ${esc(t.title)}" data-task="${t.id}" ${t.done?'checked':''}><span class="task-name">${esc(t.title)}${full?`<br><small>${esc(t.due||'No due date')} · ${esc(t.priority)} priority${t.notes?' · '+esc(t.notes):''}</small>`:''}</span><span class="subject">${esc(t.subject)}</span><span class="task-time">${t.minutes}m</span><button class="more" data-edit-task="${t.id}" aria-label="Edit ${esc(t.title)}">⋯</button></div>`).join(''):'<div class="empty">A fresh page, a fresh start.<br>Add your first study task below.</div>';}
function clockText(){return `${String(Math.floor(timer.seconds/60)).padStart(2,'0')}:${String(timer.seconds%60).padStart(2,'0')}`;}
function timerMarkup(){return `<div class="timer-scene"><div class="timer-panel"><h2>Pomodoro <span style="float:right;font-size:13px;color:#b89879">✦</span></h2><div class="tabs">${[['focus','Focus'],['short','Short break'],['long','Long break']].map(([m,l])=>`<button data-mode="${m}" class="${timer.mode===m?'active':''}">${l}</button>`).join('')}</div><div class="timer-digits" data-clock>${clockText()}</div><p class="timer-cycle" data-cycle>${cycleText()}</p><button class="primary start" data-action="timer"><span data-timer-icon>${icon(timer.running?'pause':'play')}</span><span data-timer-label>${timer.running?'Pause':timer.seconds<timer.total?'Resume':timer.mode==='focus'?'Start focus':'Start break'}</span></button><div class="timer-tools"><button class="round" data-action="sound" aria-label="Sound options" title="Sound options" data-playing="${!!audio?.kind}" aria-haspopup="dialog">${icon('music')}</button><button class="round" data-action="immersive" aria-label="Distraction-free focus">${icon('expand')}</button><button class="round" data-action="alarms" aria-label="One-time alarms" title="One-time alarms">${icon('bell')}</button><button class="round" data-action="timer-settings" aria-label="Timer settings">${icon('settings')}</button><button class="round" data-action="reset-timer" aria-label="Reset current phase" title="Reset current phase">${icon('reset')}</button></div><button class="secondary reset-pomodoro" data-action="reset-pomodoro">Reset Pomodoro</button></div><span class="timer-caption">Good coffee. Better focus.</span></div>`;}
const quests=[{id:'sessions',label:'Complete 2 Pomodoros',xp:50,coins:0,check:()=>dailySessions().length>=2},{id:'hour',label:'Study for 1 hour total',xp:0,coins:50,check:()=>dailySessions().reduce((a,s)=>a+s.minutes,0)>=60},{id:'break',label:'Take a mindful break',xp:30,coins:0,check:()=>state.quests[today()+':breakDone']},{id:'cards',label:'Review 5 flashcards',xp:0,coins:30,check:()=>Number(state.quests[today()+':reviews']||0)>=5}];
function questMarkup(){return quests.map(q=>{const claimed=state.quests[today()+':'+q.id];return `<div class="quest-row"><button class="check" style="${claimed?'background:var(--green);color:white;border-color:var(--green)':''}" data-quest="${q.id}" aria-label="Claim ${q.label}">${claimed?'✓':''}</button><span>${q.label}</span><span class="reward">${claimed?'Claimed':q.xp?'+'+q.xp+' XP':'+'+q.coins+' coins'}</span></div>`;}).join('');}
function weekChart(){const days=[];for(let i=6;i>=0;i--){const d=new Date();d.setDate(d.getDate()-i);const date=d.toLocaleDateString('en-CA');days.push({label:d.toLocaleDateString('en-US',{weekday:'short'}),value:state.sessions.filter(s=>s.date===date).reduce((a,s)=>a+s.minutes,0)});}const max=Math.max(60,...days.map(d=>d.value));return `<div class="chart"><span class="chart-label">${Math.round(max/60*10)/10}h</span>${days.map(d=>`<div class="bar-col"><div class="bar" style="height:${d.value/max*100}%" title="${d.label}: ${d.value} minutes"></div><small>${d.label}</small></div>`).join('')}</div>`;}
function metrics(){return `<div class="metrics"><div class="metric"><b>${(minutes()/60).toFixed(1)}h</b><small>Total study time</small></div><div class="metric"><b>${state.sessions.length}</b><small>Pomodoros</small></div><div class="metric"><b>${state.tasks.length?Math.round(state.tasks.filter(t=>t.done).length/state.tasks.length*100):0}%</b><small>Tasks complete</small></div></div>`;}
function dashboard(){const tasks=state.tasks.filter(t=>t.due===today());return `<div class="greeting"><div><div class="eyebrow">A little progress, every day</div><h1>${greeting()} <span class="sun">☀</span></h1><p>A focused day is a brighter you. Let’s make something good.</p></div><div class="wallet"><div class="stat-mini"><span class="coin">⭐</span><div><b>${state.xp.toLocaleString()} <span style="font-size:13px">XP</span></b><small>Lv. ${level()} · Focused learner</small><div class="progress"><span style="width:${state.xp%1000/10}%"></span></div></div></div><div class="stat-mini"><span class="coin">🪙</span><div><b>${state.coins}</b><small>Café coins</small></div></div></div></div><div class="dash-top">${timerMarkup()}<section class="card"><div class="card-head"><h2>Today’s study tasks</h2><small>${tasks.filter(t=>t.done).length} / ${tasks.length} complete</small></div>${tasks.length?taskRows(tasks):'<div class="empty">No study tasks due today.</div>'}<button class="add-task" data-action="add-task">${icon('plus')} Add a new task</button></section>${plantMarkup()}</div><div class="dash-bottom"><section class="card"><div class="card-head"><h2>✧ Daily quests</h2><small>${quests.filter(q=>state.quests[today()+':'+q.id]).length} / 4 claimed</small></div>${questMarkup()}<div class="quest-footer"><span>🎁</span>Small steps, lovely rewards.<br>Finish a quest, then tap to claim.</div></section><section class="card"><div class="card-head"><h2>🔥 Study streak</h2><button data-view="stats" aria-label="View statistics">↗</button></div><div class="streak-number">${streak()} ${streak()===1?'day':'days'}</div><small>${streak()?'You’re building something good.':'Your next session starts a new streak.'}</small><div class="week-dots">${['M','T','W','T','F','S','S'].map((day,i)=>{const d=new Date();d.setDate(d.getDate()-(d.getDay()+6)%7+i);const yes=state.sessions.some(s=>s.date===d.toLocaleDateString('en-CA'));return `<div class="day"><i class="${yes?'filled':''}">${yes?'✓':'·'}</i>${day}</div>`;}).join('')}</div><div class="quote">“Discipline today brews the freedom tomorrow.” 🌱</div></section><section class="card"><div class="card-head"><h2>Café vibes</h2><small>LAST 7 DAYS</small></div>${weekChart()}${metrics()}</section></div>`;}
let pendingTaskDraft=null;
function ensureClasses(){const removed=new Set((state.removedClasses||[]).map(c=>c.toLowerCase())),archived=new Set((state.decks||[]).filter(d=>d.archived).map(d=>d.id));state.classes=[...new Set([...(state.classes||['General']),...state.tasks.map(t=>t.subject),...state.cards.filter(c=>!archived.has(c.deckId)).map(c=>c.subject),...(state.decks||[]).filter(d=>!d.archived).map(d=>d.subject)].filter(c=>c&&!removed.has(c.toLowerCase())))];return state.classes;}
function classManager(){return '<section class="card class-manager"><div class="card-head"><h2>Classes</h2><button class="secondary" data-action="add-class">+ Add class</button></div><div class="class-list">'+(ensureClasses().map(name=>'<div class="class-row"><b>'+esc(name)+'</b><div><button class="text-link" data-edit-class="'+esc(name)+'">Edit</button><button class="text-link" data-remove-class="'+esc(name)+'">Remove</button></div></div>').join('')||'<p class="muted">Add a class to organize new sets.</p>')+'</div></section>';}
function editClassModal(name){showModal('Edit class','<form id="edit-class-form" data-class="'+esc(name)+'"><label class="field">Class name<input name="name" required maxlength="50" value="'+esc(name)+'"></label><button class="primary">Save class</button></form>');}
function renameClass(oldName,newName){newName=String(newName||'').trim();if(!newName||newName.length>50)return toast('Enter a class name up to 50 characters.');if(ensureClasses().some(c=>c!==oldName&&c.toLowerCase()===newName.toLowerCase()))return toast('That class name already exists.');state.classes=state.classes.map(c=>c===oldName?newName:c);for(const d of state.decks)if(!d.archived&&d.subject===oldName)d.subject=newName;for(const c of state.cards)if(c.subject===oldName&&!state.decks.find(d=>d.id===c.deckId)?.archived)c.subject=newName;for(const t of state.tasks)if(t.subject===oldName)t.subject=newName;state.removedClasses=(state.removedClasses||[]).filter(c=>c.toLowerCase()!==newName.toLowerCase());if(classFilter===oldName)classFilter=newName;if(deckClassFilter===oldName)deckClassFilter=newName;if(timer.subject===oldName)timer.subject=newName;save();modal.close();render();toast('Class renamed.');}
function removeClass(name){ensureDecks();state.classes=state.classes.filter(c=>c!==name);state.removedClasses=[...new Set([...(state.removedClasses||[]),name])];for(const d of state.decks)if(d.subject===name)d.archived=true;if(classFilter===name)classFilter='all';if(deckClassFilter===name)deckClassFilter='all';save();render();toast('Class removed. Its sets and flashcards are saved in Archive.');}
function classOptions(value){return ensureClasses().map(c=>'<option value="'+esc(c)+'" '+(value===c?'selected':'')+'>'+esc(c)+'</option>').join('');}
function classModal(fromTask=false){if(fromTask){const f=$('#task-form'),d=new FormData(f);pendingTaskDraft={id:f.dataset.id,title:d.get('title'),subject:d.get('subject'),minutes:Number(d.get('minutes')),due:d.get('due'),priority:d.get('priority'),notes:d.get('notes')};}else pendingTaskDraft=null;showModal('Add a class','<form id="class-form"><label class="field">Class name<input name="name" required maxlength="60" placeholder="e.g. Biology 101" autofocus></label><button class="primary">Add class</button></form>');}
function bulkTasksModal(){showModal('Add tasks for a class','<form id="bulk-task-form"><label class="field">Class<select name="subject">'+classOptions(classFilter==='all'?'General':classFilter)+'</select></label><label class="field">Tasks, one per line<textarea name="tasks" rows="9" required placeholder="Read chapter 1 | 2026-10-05 | 30&#10;Practice problems | 2026-10-07 | 45&#10;Review lecture notes"></textarea></label><p class="muted" style="font-size:11px">Use: Task title | Due date (YYYY-MM-DD) | Minutes | Priority | Notes.<br>Only the title is required. Leave optional fields empty with | separators. Defaults: no due date, 25 minutes, Medium priority.</p><p id="bulk-error" class="login-error" role="alert"></p><button class="primary">Add all tasks</button></form>');}
function parseBulkTasks(text,subject){const lines=text.split(/\r?\n/).map(l=>l.trim()).filter(Boolean);if(!lines.length)throw new Error('Add at least one task.');if(lines.length>100)throw new Error('Add up to 100 tasks in one batch.');return lines.map((line,i)=>{const parts=line.split('|').map(p=>p.trim()),[title,due='',mins='',priority='Medium',...noteParts]=parts;const minutes=mins?Number(mins):25,pr=priority||'Medium';if(!title||title.length>160)throw new Error('Line '+(i+1)+': use a title up to 160 characters.');if(due&&(!/^\d{4}-\d{2}-\d{2}$/.test(due)||Number.isNaN(Date.parse(due+'T12:00:00Z'))||new Date(due+'T12:00:00Z').toISOString().slice(0,10)!==due))throw new Error('Line '+(i+1)+': use a valid due date in YYYY-MM-DD format.');if(!Number.isInteger(minutes)||minutes<1||minutes>1440)throw new Error('Line '+(i+1)+': minutes must be a whole number from 1 to 1440.');if(!['Low','Medium','High'].includes(pr))throw new Error('Line '+(i+1)+': priority must be Low, Medium, or High.');return {id:uid(),title,subject,due,minutes,priority:pr,notes:noteParts.join(' | '),done:false,rewarded:false};});}
function taskDayGroups(tasks){
  if(!tasks.length)return taskRows(tasks,true);
  const groups=new Map();
  for(const task of [...tasks].sort((a,b)=>(a.due||'9999-12-31').localeCompare(b.due||'9999-12-31'))){const day=task.due||'';if(!groups.has(day))groups.set(day,[]);groups.get(day).push(task);}
  return [...groups].map(([day,items])=>{const label=day?new Intl.DateTimeFormat('en-US',{weekday:'long',month:'long',day:'numeric',year:'numeric'}).format(new Date(day+'T12:00:00')):'No due date';const minutes=items.reduce((total,t)=>total+(Number.isFinite(Number(t.minutes))?Math.max(0,Number(t.minutes)):0),0),hours=Math.floor(minutes/60),remainder=minutes%60,duration=hours?hours+'h'+(remainder?' '+remainder+'m':''):minutes+' min';return '<section class="task-day-group"><h2 class="task-day-heading"><span>'+esc(label)+'</span><span class="task-day-total">'+duration+' allotted</span></h2>'+taskRows(items,true)+'</section>';}).join('');
}
function tasksPage(){ensureClasses();let ts=state.tasks;if(classFilter!=='all')ts=ts.filter(t=>t.subject===classFilter);if(filter==='completed')ts=ts.filter(t=>t.done);if(filter==='upcoming')ts=ts.filter(t=>!t.done&&(!t.due||t.due>=today()));if(filter==='overdue')ts=ts.filter(t=>!t.done&&t.due&&t.due<today());return `<div class="page-title"><div class="eyebrow">One thing at a time</div><h1>Your study tasks</h1><p>Make room for what matters. We’ll keep the details here.</p></div><div class="toolbar"><button class="primary" data-action="add-task">${icon('plus')} Add task</button><button class="secondary" data-action="bulk-tasks">Add in bulk</button><button class="secondary" data-action="add-class">+ Add class</button><label class="class-filter-label">Class <select id="class-filter" class="form-input"><option value="all">All classes</option>${classOptions(classFilter)}</select></label>${['all','upcoming','completed','overdue'].map(f=>`<button data-filter="${f}" class="secondary" style="${filter===f?'background:var(--green);color:white':''}">${f[0].toUpperCase()+f.slice(1)}</button>`).join('')}</div><section class="card full-tasks">${['all','upcoming'].includes(filter)?taskDayGroups(ts):taskRows(ts,true)}</section>`;}
function focusPage(){const classes=ensureClasses();if(!classes.includes(timer.subject))timer.subject=classes[0]||'General';return `<div class="page-title"><div class="eyebrow">Find your flow</div><h1>A moment to focus.</h1><p>Settle in, take a breath, and give yourself one good session.</p></div><div class="focus-page">${timerMarkup()}<div class="toolbar focus-toolbar"><label>Studying <select id="timer-subject" class="form-input">${classes.length?classOptions(timer.subject):'<option value="General">General</option>'}</select></label><button class="secondary" data-action="skip">Skip to next phase</button><button class="secondary" data-action="alarms">${icon('bell')} Alarms</button><small>Focus sessions earn 50 XP + 25 coins.</small></div></div>`;}
function ensureDecks(){
  state.decks||=[];
  for(const card of state.cards){
    if(!state.decks.some(d=>d.id===card.deckId)){
      let deck=state.decks.find(d=>d.subject===card.subject&&d.legacy);
      if(!deck){deck={id:uid(),name:card.subject+' · saved cards',subject:card.subject,due:'',legacy:true};state.decks.push(deck);}
      card.deckId=deck.id;
    }
  }
  ensureClasses();
}
function shuffleStudySet(){const original=reviewCards(),cards=[...original];if(!cards.length)return;for(let i=cards.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[cards[i],cards[j]]=[cards[j],cards[i]];}if(cards.length>1&&cards.every((c,i)=>c.id===original[i].id))cards.push(cards.shift());let index=0;state.cards=state.cards.map(c=>c.deckId===activeDeck?cards[index++]:c);reviewIndex=0;flipped=false;save();render();}
function reviewCards(){ensureDecks();return state.cards.filter(c=>c.deckId===activeDeck);}
async function toggleFlashcardFullscreen(){if(flashcardFullscreen)return exitFlashcardFullscreen();if(!state.decks.some(d=>d.id===activeDeck))return;flashcardFullscreen=true;render();document.querySelector('[data-action="flashcard-fullscreen"]')?.focus?.();if(!document.fullscreenElement&&document.documentElement?.requestFullscreen){nativeFlashcardFullscreen=true;try{await document.documentElement.requestFullscreen();}catch{nativeFlashcardFullscreen=false;}}}
