document.addEventListener?.('keydown',e=>{if(e.key==='Escape'&&flashcardFullscreen&&!modal.open){e.preventDefault();exitFlashcardFullscreen();}});
document.addEventListener?.('fullscreenchange',()=>{if(nativeFlashcardFullscreen&&!document.fullscreenElement){nativeFlashcardFullscreen=false;flashcardFullscreen=false;render();document.querySelector('[data-action="flashcard-fullscreen"]')?.focus?.();}});
