function roomCharacter(id,rotation=0){const n=Math.max(0,avatars.findIndex(a=>a[0]===id)),row=Math.floor(((rotation%360)+360)%360/90),tops=[0,290,560,810],heights=[300,280,260,214],h=heights[row],top=tops[row];return '<span class="iso-character-sprite" style="background-size:600% '+(1024/h*100)+'%;background-position:'+(n*20)+'% '+(top/(1024-h)*100)+'%"></span>';}
