async function submit(e){e.preventDefault();const f=e.target,d=new FormData(f);if(f.id==='alarm-form')return saveAlarmForm(f,d);if(f.id==='notebook-form')return saveNotebookForm(f,d);if(f.id==='notebook-folder-form')return saveNotebookFolder(f,d);if(f.id==='notebook-page-form')return saveNotebookPage(f,d);if(f.id==='search-form')return showSearch(d.get('query'));if(f.id==='deck-form')return saveDeckForm(f,d);if(f.id==='edit-class-form')return renameClass(f.dataset.class,d.get('name'));if(f.id==='class-form'){const name=d.get('name').trim();if(!name)return toast('Please enter a class name.');const existing=ensureClasses().find(c=>c.toLowerCase()===name.toLowerCase());if(!existing)state.classes.push(name);state.removedClasses=(state.removedClasses||[]).filter(c=>c.toLowerCase()!==name.toLowerCase());save();modal.close();if(pendingDeckDraft){pendingDeckDraft.subject=existing||name;deckModal(false,pendingDeckDraft);pendingDeckDraft=null;}else if(pendingTaskDraft){pendingTaskDraft.subject=existing||name;taskModal(pendingTaskDraft.id,pendingTaskDraft);pendingTaskDraft=null;}else{classFilter=existing||name;render();}toast(existing?'That class is already available.':'Class added.');}if(f.id==='bulk-task-form'){try{const ts=parseBulkTasks(d.get('tasks'),d.get('subject'));state.tasks.push(...ts);save();filter='all';classFilter=d.get('subject');modal.close();render();toast(ts.length+' tasks added to '+d.get('subject')+'.');}catch(err){$('#bulk-error').textContent=err.message;}}if(f.id==='task-form'){const id=f.dataset.id,old=state.tasks.find(t=>t.id===id);const t={...old,id:id||uid(),title:d.get('title').trim(),subject:d.get('subject').trim(),minutes:Number(d.get('minutes')),due:d.get('due'),priority:d.get('priority'),notes:d.get('notes'),done:old?.done||false,rewarded:old?.rewarded||false};if(!t.title||!t.subject)return toast('Please add a task and subject.');if(old)state.tasks[state.tasks.indexOf(old)]=t;else state.tasks.push(t);save();modal.close();render();toast('Task saved. One step closer.');}if(f.id==='timer-settings-form'){for(const k of ['focus','short','long'])state.settings[k]=Number(d.get(k));save();resetTimer();modal.close();render();}if(f.id==='exam-form'){state.exam={name:d.get('name'),date:d.get('date'),goal:Number(d.get('goal'))};save();modal.close();render();}if(f.id==='settings-form'){const zone=d.get('timeZone')||state.settings.timeZone||window.CoffeeClock.defaultTimeZone();if(!window.CoffeeClock.validTimeZone(zone))return toast('Choose a valid time zone.');state.settings.timeZone=zone;state.name=d.get('name');state.settings.daily=Number(d.get('daily'));state.settings.weekly=Number(d.get('weekly'));state.settings.dark=false;save();render();toast('Your café feels a little more you.');}if(f.id==='auth-form'){const button=f.querySelector('button.primary');button.disabled=true;button.textContent='Opening your café…';try{if(authMode==='signup'){const cred=await cloud.createUserWithEmailAndPassword(cloud.auth,d.get('email'),d.get('password'));await cloud.updateProfile(cred.user,{displayName:d.get('name')});if(state&&user?.uid===cred.user.uid){state.name=d.get('name');save();render();}}else await cloud.signInWithEmailAndPassword(cloud.auth,d.get('email'),d.get('password'));}catch(err){const errors={'auth/invalid-credential':'That email or password doesn’t match. Try again.','auth/email-already-in-use':'That email already has a café. Try logging in.','auth/weak-password':'Choose a password with at least 6 characters.','auth/network-request-failed':'Check your internet connection, then try again.','auth/too-many-requests':'Too many attempts. Please try again later.'};if($('#auth-error')){$('#auth-error').textContent=errors[err.code]||'Could not open your café. Check Firebase configuration and try again.';button.disabled=false;button.textContent=authMode==='signup'?'Create account':'Log in';}}}}
app.addEventListener('submit',e=>submit(e).catch(console.error));modal.addEventListener('submit',e=>submit(e).catch(console.error));
async function handleAuthState(u){
  // A deliberately opened guest café stays separate from a restored Firebase account.
  if(guest)return;
  if(!u){ready=false;user=null;clearRememberedSession();renderLogin();return;}
  ready=false;state=null;user=u;
  try{
    const snap=await cloud.getDoc(cloud.doc(cloud.db,'users',u.uid));
    if(user?.uid!==u.uid||guest)return;
    state=snap.exists()?snap.data().data:initial();state.name=u.displayName||state.name;
    migrateCafe();ensureDecks();cafeGuests=[];lastGuestArrival=0;ready=true;resetTimer();restorePage();render();
  }catch(err){if(user?.uid!==u.uid||guest)return;ready=false;renderLogin();toast('Could not load your private café. Check Firestore rules and your connection.');}
}
async function init(){
  app.innerHTML='<main class="login"><section class="card"><h2>Brewing your café…</h2><p>Please take a moment to settle in.</p></section></main>';
  if(resumeGuestSession())loadGuest(true);
  if(window.FIREBASE_CONFIG){
    try{
      const base='https://www.gstatic.com/firebasejs/12.19.0/';
      const [fb,auth,fs]=await Promise.all([import(base+'firebase-app.js'),import(base+'firebase-auth.js'),import(base+'firebase-firestore.js')]);
      const fa=fb.initializeApp(window.FIREBASE_CONFIG);
      cloud={...auth,...fs,auth:auth.getAuth(fa),db:fs.getFirestore(fa)};
      await auth.setPersistence(cloud.auth,auth.browserLocalPersistence);
      auth.onAuthStateChanged(cloud.auth,handleAuthState);
      // Wait for Firebase's initial auth result before showing a login form.
      return;
    }catch(err){console.error(err);toast('Firebase could not connect. Guest mode is still available.');}
  }
  if(!ready)renderLogin();
}
init();
